// Define temas rotativos para os posts
const temas = [
  { tema: 'dica de saúde bucal', tipo: 'dica', emoji: '🦷' },
  { tema: 'mito vs verdade sobre dentes', tipo: 'mito_verdade', emoji: '✅' },
  { tema: 'cuidados pós-tratamento dentário', tipo: 'cuidado', emoji: '💊' },
  { tema: 'importância da visita semestral ao dentista', tipo: 'conscientizacao', emoji: '📅' },
  { tema: 'alimentos que prejudicam os dentes', tipo: 'alimentacao', emoji: '🍎' },
  { tema: 'benefícios do clareamento dental', tipo: 'procedimento', emoji: '✨' },
  { tema: 'como escovar os dentes corretamente', tipo: 'tutorial', emoji: '🪥' },
  { tema: 'tratamento de canal: desmistificando medos', tipo: 'desmistificacao', emoji: '😌' },
  { tema: 'cuidados com implantes dentários', tipo: 'procedimento', emoji: '🔩' },
  { tema: 'ortodontia: quando começar?', tipo: 'conscientizacao', emoji: '😁' }
];

// Seleciona tema baseado no dia do ano para variedade
const diaAno = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
const tema = temas[diaAno % temas.length];

const diasSemana = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const diaSemana = diasSemana[new Date().getDay()];

return [{ json: { ...tema, diaSemana, dataPost: new Date().toLocaleDateString('pt-BR') } }];

