const claudeResponse = $input.first().json;
const textoRaw = claudeResponse.content[0].text;

// Parse do JSON retornado pelo Claude
let conteudo;
try {
  // Remove possível markdown
  const jsonMatch = textoRaw.match(/```json([\s\S]*?)```/) || textoRaw.match(/({[\s\S]*})/);
  const jsonStr = jsonMatch ? jsonMatch[1].trim() : textoRaw;
  conteudo = JSON.parse(jsonStr);
} catch (e) {
  // Fallback caso Claude não retorne JSON puro
  conteudo = {
    legenda_instagram: textoRaw.substring(0, 2200),
    texto_story_whatsapp: textoRaw.substring(0, 200),
    hashtags: ['#odontologia', '#dentista', '#saudebuucal', '#dente'],
    call_to_action: 'Agende sua consulta!',
    ideia_visual: 'Post informativo sobre saúde bucal'
  };
}

return [{
  json: {
    ...conteudo,
    tema: $('Seleciona Tema do Dia').item.json.tema
  }
}];

